/**
 * Per-member project mutes. A mute row exists only while the member has muted
 * the project; unmuting deletes it.
 */
import { and, eq } from "drizzle-orm";
import { getDb, notificationMutes } from "@/server/db";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { IsoTimestamp, OrgId, ProjectId, UserId } from "@/types/common";

/** Idempotent: muting an already-muted project changes nothing. */
export async function insertMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .insert(notificationMutes)
    .values({ orgId, userId, projectId, createdAt: at, updatedAt: at })
    .onConflictDoNothing()
    .run();
}

/** Idempotent: unmuting a project that is not muted changes nothing. */
export async function deleteMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(notificationMutes)
    .where(
      and(
        orgPredicate(notificationMutes.orgId, orgId),
        eq(notificationMutes.userId, userId),
        eq(notificationMutes.projectId, projectId),
      ),
    )
    .run();
}

export async function isProjectMuted(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<boolean> {
  const row = getDb()
    .select({ projectId: notificationMutes.projectId })
    .from(notificationMutes)
    .where(
      and(
        orgPredicate(notificationMutes.orgId, orgId),
        eq(notificationMutes.userId, userId),
        eq(notificationMutes.projectId, projectId),
      ),
    )
    .get();
  return row !== undefined;
}

export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: notificationMutes.projectId })
    .from(notificationMutes)
    .where(
      and(
        orgPredicate(notificationMutes.orgId, orgId),
        eq(notificationMutes.userId, userId),
      ),
    )
    .all();
  return rows.map((row) => brandId<ProjectId>(row.projectId));
}
